update public.products set description='Chicken wings are bone-in poultry portions with skin, suitable for frying, grilling, baking, roasting, stews and seasoned wing dishes.', handling_protocols=array['Keep raw wings cold and separated from ready-to-eat foods.','Do not wash raw chicken; clean hands, utensils and preparation surfaces thoroughly after handling.','Cook the thickest part to at least 74°C / 165°F.']::text[], storage_tips=array['If supplied chilled, refrigerate at 4°C or below and use within 1–2 days.','If supplied frozen, keep at about -18°C or below and use within about 6–9 months for best quality.','After refrigerator thawing, cook within 1–2 days.']::text[] where name='Chicken Wings' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
